    async def set_session_run_feedback(self, session_id: str, run_id: str, body: Union[_m.SetSessionRunFeedbackRequest, Dict[str, Any]], *, request_options: Optional[RequestOptions] = None) -> _m.RunFeedbackSet:
        """Save feedback/reaction for a session run

        `message_id` is stored as sent. The canonical form is the id `GET
        /sessions/{sessionId}/messages` serves for the entry (`{run_id}`, `{run_id}-reply[-N]`,
        `{run_id}-user-N`, `{run_id}-tool-N`, `{run_id}-system-N`); any other string is accepted —
        older iOS builds send `{run_id}-{timestamp}-assistant-{hash}` and App Store never retires
        them — but cannot be matched back to the transcript, and each such arrival is counted per
        day (owner's decision 2026-09-11, option A: a 422 comes no earlier than a month of zero).

        WRITE SEMANTICS: replaces. The caller's row for this `message_id` is overwritten whole with
        `reaction`, a fresh `created_at` and `reason` when one is sent, so an omitted or empty
        `reason` drops a previously stored one. Other callers' rows and other messages' rows are
        untouched.

        `PUT /api/v1/sessions/{sessionId}/runs/{runId}/feedback`

        Required scopes: `sessions:write`.
        """
        return _cast("_m.RunFeedbackSet", await self._client._request(
            "PUT",
            f"/api/v1/sessions/{_segment(session_id)}/runs/{_segment(run_id)}/feedback",
            body=_Body(body),
            idempotent=True,
            response=_Response(type=_m.RunFeedbackSet),
            request_options=request_options,
        ))

    def stream_session_events(self, session_id: str, *, token: Optional[str] = None, resume: Optional[str] = None, event_schema: Optional[int] = None, last_event_id: Optional[str] = None, request_options: Optional[RequestOptions] = None) -> AsyncEventStream:
        """Stream session events (SSE)

        Server-Sent Events of the session: `connected`, `run_added`, every run event by type,
        `run_done`, `session_closed`, and — for the session's drawings (docs/DESIGNER-CANVAS.md
        §5.4) — `drawing.created` (data: Drawing) and `drawing.ops` (data: { drawing_id, from_seq,
        to_seq, items: DrawingJournalEntry[] }, up to 100 entries a frame). Event ids are
        `<runId>:<seq>` and `drawing:<drawingId>:<seq>`; send the last one as `Last-Event-ID` to
        resume. An unknown event name is ignored by clients, which is how new ones arrive. A session
        run also emits `session.context` (payload: SessionContext plus `session_id`) after the run's
        last model call and before `run.completed` — the context bar's live update, since
        2026-10-15.

        `GET /api/v1/sessions/{sessionId}/events`

        Required scopes: `sessions:read`.

        Returns a server-sent event stream; iterate it with `async for`.
        """
        return self._client._stream(
            f"/api/v1/sessions/{_segment(session_id)}/events",
            query=[("token", token), ("resume", resume), ("event_schema", event_schema)],
            headers=[("Last-Event-ID", last_event_id)],
            request_options=request_options,
        )

